<?php error_reporting(E_ALL); ini_set('display_errors', '1'); echo "PHP started.<br><br>"; $host = "localhost"; $dbname = "login_system"; $dbuser = "login_app"; $dbpass = "YOUR_MYSQL_PASSWORD"; echo "Attempting database connection...<br><br>"; try { $pdo = new PDO( "mysql:host=$host;dbname=$dbname;charset=utf8mb4", $dbuser, $dbpass ); echo "<strong>Database connection successful!</strong>"; } catch (PDOException $e) { echo "<strong>Database connection failed:</strong><br>"; echo htmlspecialchars($e->getMessage()); } ?>